CREATE VIEW v_superhero AS SELECT "superhero"."id", "superhero"."superhero_name" AS "superhero_name", "superhero"."full_name", "gender"."gender", "eye_colour"."colour" AS "eye_colour", "hair_colour"."colour" AS "hair_colour", "skin_colour"."colour" AS "skin_colour", "race"."race", "publisher"."publisher_name", "alignment"."alignment", "superhero"."height_cm", "superhero"."weight_kg", superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, gender.id AS gender_id_2, eye_colour.id AS eye_colour_id_2, hair_colour.id AS hair_colour_id_2, skin_colour.id AS skin_colour_id_2, race.id AS race_id_2, publisher.id AS publisher_id_2, alignment.id AS alignment_id_2 FROM "superhero" LEFT JOIN "gender" ON "superhero"."gender_id" = "gender"."id" LEFT JOIN "colour" AS eye_colour ON "superhero"."eye_colour_id" = "eye_colour"."id" LEFT JOIN "colour" AS hair_colour ON "superhero"."hair_colour_id" = "hair_colour"."id" LEFT JOIN "colour" AS skin_colour ON "superhero"."skin_colour_id" = "skin_colour"."id" LEFT JOIN "race" ON "superhero"."race_id" = "race"."id" LEFT JOIN "publisher" ON "superhero"."publisher_id" = "publisher"."id" LEFT JOIN "alignment" ON "alignment"."id" = "superhero"."alignment_id";

CREATE VIEW v_hero_power AS SELECT "superhero"."id" AS "hero_id", "superhero"."superhero_name", "superpower"."power_name", hero_power.hero_id AS hero_power_hero_id, hero_power.power_id, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, superpower.id FROM "hero_power" LEFT JOIN "superhero" ON "hero_power"."hero_id" = "superhero"."id" LEFT JOIN "superpower" ON "hero_power"."power_id" = "superpower"."id";

CREATE VIEW v_hero_attribute AS SELECT "superhero"."id" AS "hero_id", "superhero"."superhero_name", "attribute"."attribute_name", "hero_attribute"."attribute_value", hero_attribute.hero_id AS hero_attribute_hero_id, hero_attribute.attribute_id, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, attribute.id FROM "hero_attribute" LEFT JOIN "superhero" ON "hero_attribute"."hero_id" = "superhero"."id" LEFT JOIN "attribute" ON "hero_attribute"."attribute_id" = "attribute"."id";

CREATE VIEW v_attribute_gender_hero_attribute_superhero AS SELECT attribute.id, attribute.attribute_name, hero_attribute.hero_id, hero_attribute.attribute_id, hero_attribute.attribute_value, superhero.id AS superhero_id, superhero.superhero_name, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, gender.id AS gender_id_2, gender.gender FROM attribute INNER JOIN hero_attribute ON attribute.id = hero_attribute.attribute_id INNER JOIN superhero ON hero_attribute.hero_id = superhero.id INNER JOIN gender ON superhero.gender_id = gender.id;

CREATE VIEW v_attribute_hero_attribute_publisher_superhero AS SELECT attribute.id, attribute.attribute_name, hero_attribute.hero_id, hero_attribute.attribute_id, hero_attribute.attribute_value, superhero.id AS superhero_id, superhero.superhero_name, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, publisher.id AS publisher_id_2, publisher.publisher_name FROM attribute INNER JOIN hero_attribute ON attribute.id = hero_attribute.attribute_id INNER JOIN superhero ON hero_attribute.hero_id = superhero.id INNER JOIN publisher ON superhero.publisher_id = publisher.id;

CREATE VIEW v_colour_hero_power_superhero_superpower AS SELECT colour.id, colour.colour, superhero.id AS superhero_id, superhero.superhero_name, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, hero_power.hero_id, hero_power.power_id, superpower.id AS superpower_id, superpower.power_name FROM colour INNER JOIN superhero ON colour.id = superhero.eye_colour_id INNER JOIN hero_power ON superhero.id = hero_power.hero_id INNER JOIN superpower ON hero_power.power_id = superpower.id;

CREATE VIEW v_gender_hero_power_superhero_superpower AS SELECT gender.id, gender.gender, superhero.id AS superhero_id, superhero.superhero_name, superhero.full_name, superhero.gender_id, superhero.eye_colour_id, superhero.hair_colour_id, superhero.skin_colour_id, superhero.race_id, superhero.publisher_id, superhero.alignment_id, superhero.height_cm, superhero.weight_kg, hero_power.hero_id, hero_power.power_id, superpower.id AS superpower_id, superpower.power_name FROM gender INNER JOIN superhero ON gender.id = superhero.gender_id INNER JOIN hero_power ON superhero.id = hero_power.hero_id INNER JOIN superpower ON hero_power.power_id = superpower.id;
